package eval

func recurringDowntimeSuite() Suite {
	base := recipeCatalogSuite()
	activity := map[string]any{"activity_id": "activity-training", "name": "Weapon training", "cycles_required": 2}
	createdAllocation := map[string]any{"character_id": "play-char-w", "activity_id": "activity-training", "cycles_completed": 0, "completions": 0}
	return Suite{ID: "072-recurring-downtime", Name: "Campaign Play 072: Recurring Downtime", Tests: append(base.Tests,
		playTest("play-downtime-player-create-forbidden", "Players cannot create downtime activities", "POST", "/v1/play/campaigns/play-2/downtime/activities", activity, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-downtime-invalid-id", "Downtime activity creation requires a nonempty activity ID", "POST", "/v1/play/campaigns/play-2/downtime/activities", map[string]any{"activity_id": "", "name": "Weapon training", "cycles_required": 2}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-downtime-invalid-name", "Downtime activity creation requires a nonempty name", "POST", "/v1/play/campaigns/play-2/downtime/activities", map[string]any{"activity_id": "activity-bad-name", "name": "", "cycles_required": 2}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-downtime-invalid-cycles-low", "Downtime activity cycles must be at least one", "POST", "/v1/play/campaigns/play-2/downtime/activities", map[string]any{"activity_id": "activity-bad-low", "name": "Bad cycles", "cycles_required": 0}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-downtime-invalid-cycles-high", "Downtime activity cycles must be at most ten", "POST", "/v1/play/campaigns/play-2/downtime/activities", map[string]any{"activity_id": "activity-bad-high", "name": "Bad cycles", "cycles_required": 11}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTestExactJSON("play-downtime-create-training", "DM creates a deterministic recurring downtime activity", "POST", "/v1/play/campaigns/play-2/downtime/activities", activity, map[string]string{"Authorization": dmAuth}, 201, activity),
		playTest("play-downtime-duplicate-activity", "Duplicate downtime activity IDs conflict", "POST", "/v1/play/campaigns/play-2/downtime/activities", activity, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTest("play-downtime-allocate-dm-forbidden", "DM cannot allocate downtime to a character", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/downtime/allocations", map[string]any{"activity_id": "activity-training"}, map[string]string{"Authorization": dmAuth}, 403, nil),
		playTest("play-downtime-allocate-non-owner-forbidden", "Players cannot allocate downtime for another player's character", "POST", "/v1/play/campaigns/play-2/characters/play-char-b/downtime/allocations", map[string]any{"activity_id": "activity-training"}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-downtime-allocate-unknown-activity", "Unknown downtime activities return 404 on allocation", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/downtime/allocations", map[string]any{"activity_id": "activity-missing"}, map[string]string{"Authorization": playerAAuth}, 404, nil),
		playTestExactJSON("play-downtime-allocate-training", "Player owner allocates recurring downtime once", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/downtime/allocations", map[string]any{"activity_id": "activity-training"}, map[string]string{"Authorization": playerAAuth}, 201, createdAllocation),
		playTest("play-downtime-duplicate-allocation", "Duplicate downtime allocations conflict", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/downtime/allocations", map[string]any{"activity_id": "activity-training"}, map[string]string{"Authorization": playerAAuth}, 409, nil),
		playTest("play-downtime-progress-dm-forbidden", "DM cannot progress a downtime allocation", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/downtime/allocations/activity-training/progress", nil, map[string]string{"Authorization": dmAuth}, 403, nil),
		playTest("play-downtime-progress-non-owner-forbidden", "Players cannot progress another player's downtime allocation", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/downtime/allocations/activity-training/progress", nil, map[string]string{"Authorization": playerBAuth}, 403, nil),
		playTest("play-downtime-progress-unknown-allocation", "Unknown downtime allocations return 404 on progress", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/downtime/allocations/activity-missing/progress", nil, map[string]string{"Authorization": playerAAuth}, 404, nil),
		playTestExactJSON("play-downtime-progress-first-cycle", "Progress increments cycles_completed before completion", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/downtime/allocations/activity-training/progress", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "activity_id": "activity-training", "cycles_completed": 1, "completions": 0}),
		playTestExactJSON("play-downtime-progress-first-completion", "Second progress completes once and resets cycle progress", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/downtime/allocations/activity-training/progress", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "activity_id": "activity-training", "cycles_completed": 0, "completions": 1}),
		playTestExactJSON("play-downtime-member-get-allocation", "Campaign members can read exact downtime allocation", "GET", "/v1/play/campaigns/play-2/characters/play-char-w/downtime/allocations/activity-training", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"character_id": "play-char-w", "activity_id": "activity-training", "cycles_completed": 0, "completions": 1}),
		playTestExactJSON("play-downtime-progress-repeat-cycle", "Recurring downtime can start a second completion", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/downtime/allocations/activity-training/progress", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "activity_id": "activity-training", "cycles_completed": 1, "completions": 1}),
		playTestExactJSON("play-downtime-progress-second-completion", "Recurring downtime completes a second time via REST", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/downtime/allocations/activity-training/progress", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "activity_id": "activity-training", "cycles_completed": 0, "completions": 2}),
	)}
}
